exercises.starter_code:
public class Main {
    static int count;
    static void increment() {}
    public static void main(String[] args) {}
}

exercises.solution:
public class Main {
    static int count;
    static void increment() { count++; }
    public static void main(String[] args) {
        System.out.println("Count: " + count);
        increment();
        System.out.println("Incremented: " + count);
    }
}

